// ── PDF page layout math ───────────────────────────────────────────────────
export const PAGE_GAP = 12; // px between panes in two-page (spread) view

// Scale so `perView` pages (1 = single, 2 = side-by-side spread) fit fully
// inside the container — both dimensions, so the whole page is visible
// without scrolling. Centering happens in the layout, not here.
export function computeFitZoom(vp, containerEl, perView) {
  const gap    = perView === 2 ? PAGE_GAP : 0;
  const availW = (containerEl.clientWidth - 4 - gap) / perView;
  const availH = containerEl.clientHeight - 4;
  return Math.max(0.3, +(Math.min(availW / vp.width, availH / vp.height)).toFixed(2));
}

// Half-page (top/bottom split) mode: only the page WIDTH needs to fit the
// container — height is shared across two stacked panes whose split point
// is controlled by the draggable divider, not by this fit calculation.
export function computeFitZoomHalf(vp, containerEl) {
  const availW = containerEl.clientWidth - 4;
  return Math.max(0.3, +(availW / vp.width).toFixed(2));
}
